  1	#include <stdint.h>
  2	#include "stm32f469xx.h"
  3	#include "FreeRTOS.h"
  4	#include "task.h"
  5	#include "queue.h"
  6	
  7	/* Hàng đợi truyền tín hiệu sự kiện từ nút bấm PA0 sang tác vụ LED3 */
  8	static QueueHandle_t xButtonQueue = NULL;
  9	
 10	/* Khởi tạo ngoại vi phần cứng: 4 LED và nút WAKEUP PA0 */
 11	static void prvSetupHardware(void)
 12	{
 13	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
 14	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
 15	
 16	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
 17	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
 18	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
 19	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
 20	
 21	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
 22	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
 23	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
 24	    GPIOG->BSRR = (1UL << LED1_PIN);
 25	
 26	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
 27	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
 28	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
 29	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
 30	
 31	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
 32	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
 33	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
 34	    GPIOK->BSRR = (1UL << LED4_PIN);
 35	}
 36	
 37	/* Task 1: Nháy LED1 (PG6) theo chu kỳ 1000 ms (500 ms bật, 500 ms tắt) */
 38	static void vTaskLED1(void *pvParameters)
 39	{
 40	    (void)pvParameters;
 41	    for (;;) {
 42	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
 43	        vTaskDelay(pdMS_TO_TICKS(500));
 44	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
 45	        vTaskDelay(pdMS_TO_TICKS(500));
 46	    }
 47	}
 48	
 49	/* Task 2: Nháy LED2 (PD4) theo chu kỳ 400 ms (200 ms bật, 200 ms tắt) */
 50	static void vTaskLED2(void *pvParameters)
 51	{
 52	    (void)pvParameters;
 53	    for (;;) {
 54	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
 55	        vTaskDelay(pdMS_TO_TICKS(200));
 56	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
 57	        vTaskDelay(pdMS_TO_TICKS(200));
 58	    }
 59	}
