 61	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queue */
 62	static void vTaskButton(void *pvParameters)
 63	{
 64	    (void)pvParameters;
 65	    uint8_t prev_state = 0;
 66	
 67	    for (;;) {
 68	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
 69	        if (state && !prev_state) {
 70	            uint32_t msg = 1;
 71	            if (xButtonQueue != NULL) {
 72	                xQueueSend(xButtonQueue, &msg, 0);
 73	            }
 74	        }
 75	        prev_state = state;
 76	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
 77	    }
 78	}
 79	
 80	/* Task 3: Chờ tín hiệu từ Queue để đổi trạng thái LED3 (PD5) */
 81	static void vTaskLED3(void *pvParameters)
 82	{
 83	    (void)pvParameters;
 84	    uint32_t rx_msg = 0;
 85	    uint8_t led_state = 0;
 86	
 87	    for (;;) {
 88	        if (xQueueReceive(xButtonQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
 89	            led_state = !led_state;
 90	            if (led_state) {
 91	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
 92	            } else {
 93	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
 94	            }
 95	        }
 96	    }
 97	}
